ee:variables.ee:set-variable:
output application/json
---
{
	"method": "POST",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.token'),
	"basePath": Mule::p('linka.basePath'),
	"queryParams": {
		"key": Mule::p('secure::linka.username'),
		"value": Mule::p('secure::linka.password')
	}
}

set-variable.value:
#[output application/json
---
{
	"method": "GET",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.invoices'),
	"basePath": Mule::p('linka.basePath'),
	"queryParams": {
		//"issue_date": "24-07-2025",
		"reception_date":  	vars.date,
		"eval_status": "2"
	},
	"headers": {
		"Authorization": "Bearer " ++ vars.accessToken.access
	}
}]

logger.message:
#[output application/json
---
{
	"correlationId": vars.correlationId,
	"message": "No invoices received from linka"
}]

set-variable.value:
#[output application/json
---
{
	"method": "GET",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.file'),
	"basePath": Mule::p('linka.basePath'),
	"uriParams": {
	   "fileId": payload.id
	} ,
	"headers": {
		"Authorization": "Bearer " ++ vars.accessToken.access
	}
}]

ee:variables.ee:set-variable:
%dw 2.0 output application/java import toBase64 from dw::core::Binaries
var isXml = (lower(payload.name) endsWith ".xml") or (typeOf(vars.invoiceFileResponse) == Object)
var invoiceFile = if (isXml) write(vars.invoiceFileResponse, "application/xml") // Raw XML string else toBase64(vars.invoiceFileResponse as Binary) // Base64 for PDF
--- { "fileData" : invoiceFile, "name" : payload.name, "fileID" : payload.id, "fileType" : payload."type", "uploadDate" : payload.upload_date, "invoiceId" : vars.invoiceId["generatedKeys"]["GENERATED_KEYS"] as Number }

logger.message:
#[output application/json
---
{
	"correlationId": vars.correlationId,
	"message": "No files received from Linka"
}]

#[output application/json
---
{
	"correlationId": vars.correlationId,
	"message": "Invoice has already been inserted "
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"InvoiceNumber": vars.invoiceData.sn
}

%dw 2.0
output application/json
---
{
	"invoiceID": vars.existingInvoiceId[0].id
}

set-variable.value:
#[output application/json
---
{
	"method": "GET",
	"host": Mule::p('linka.host'),
	"port": Mule::p('linka.port'),
	"path": Mule::p('linka.path.file'),
	"basePath": Mule::p('linka.basePath'),
	"uriParams": {
	   "fileId": payload.id
	} ,
	"headers": {
		"Authorization": "Bearer " ++ vars.accessToken.access
	}
}]

ee:variables.ee:set-variable:
%dw 2.0 output application/java import toBase64 from dw::core::Binaries
var isXml = (lower(payload.name) endsWith ".xml") or (typeOf(vars.invoiceFileResponse) == Object)
var invoiceFile = if (isXml) write(vars.invoiceFileResponse, "application/xml") // Raw XML string else toBase64(vars.invoiceFileResponse as Binary) // Base64 for PDF
--- { "fileData" : invoiceFile, "name" : payload.name, "fileID" : payload.id, "fileType" : payload."type", "uploadDate" : payload.upload_date, "invoiceId": vars.existingInvoiceId[0].id}

logger.message:
#[output application/json
---
{
	"correlationId": vars.correlationId,
	"message": "No files received from Linka"
}]
